// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 sendAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        sendAmount = bound(sendAmount, 0, address(this).balance);

        address originalOwner = c.owner();
        vm.deal(address(this), sendAmount);
        vm.prank(address(this));
        c.sendMoney(nonOwner, sendAmount);

        uint256 balanceBefore = address(c).balance;
        bool ownerWithdrawSucceeded;
        vm.prank(originalOwner);
        try c.withdrawAll() {
            ownerWithdrawSucceeded = true;
        } catch {
            ownerWithdrawSucceeded = false;
        }

        assertTrue(ownerWithdrawSucceeded || balanceBefore == 0);
    }
}
